    #[must_use]
    pub fn is_unknown(&self) -> bool {
        matches!(self, CaliforniaHandRank::Unknown)
    }

    #[must_use]
    pub fn get_hand_rank(&self) -> CaliforniaHandRankValue {
        if self.is_unknown() {
            0
        } else {
            *self as CaliforniaHandRankValue
        }
    }
